    61→        fun addEntry(termList: MutableList<RuleEntry>, ref: CharVector, type: String?, posTag: PosTagProbEntry.PosTag?, startOffset: Int, endOffset: Int, spaceDictionary: SpaceDictionary?) {
    62→            var entryType = type
    63→            if (entryType == FULL_STRING) {
    64→                // NOP
    65→            } else if (posTag == PosTagProbEntry.PosTag.N) {
    66→                entryType = HANGUL
    67→            } else if (posTag == PosTagProbEntry.PosTag.DIGIT) {
