    98→        fun split(entry: RuleEntry, queue: MutableList<RuleEntry>, baseInx: Int): Int {
    99→            logger.trace("split entry ({}) : {}~{}", entry, entry.start, entry.length)
   100→            var ptype: String? = null
   101→            var ctype: String? = null
   102→            var st = 0
   103→            var addInx = 0
   104→            val offsetStarts = entry.startOffset
   105→            for (inx in 0 until entry.length) {
   106→                val ch = entry.buf[entry.start + inx]
   107→                ctype = getType(ch)
   108→                if (ptype != null && ptype != ctype) {
   109→                    val entryClone = entry.clone()
   110→                    entryClone.start = entry.start + st
   111→                    entryClone.length = inx - st
   112→                    entryClone.type = ptype
   113→                    entryClone.startOffset = offsetStarts + st
   114→                    entryClone.endOffset = offsetStarts + st + entryClone.length
   115→                    entryClone.modifiable = true
   116→                    logger.trace("add splited entry : ({}) : {}~{}", entryClone, entryClone.start, entryClone.length)
   117→                    if (entryClone.type != WHITESPACE) {
   118→                        queue.add(baseInx + addInx, entryClone)
   119→                        addInx++
   120→                    }
   121→                    if (inx > 0) {
   122→                        entryClone.subEntry = ArrayList()
   123→                        entryClone.synonym = null
   124→                    }
   125→                    st = inx
   126→                }
   127→                ptype = ctype
   128→            }
   129→            if (addInx >= 0 && st < entry.length) {
   130→                val entryClone = entry.clone()
   131→                if (ptype == null) {
   132→                    ptype = ctype
   133→                }
   134→                entryClone.start = entry.start + st
   135→                entryClone.length = entry.length - st
   136→                entryClone.startOffset = offsetStarts + st
   137→                entryClone.endOffset = offsetStarts + st + entryClone.length
   138→                entryClone.type = ptype
   139→                entryClone.subEntry = ArrayList()
   140→                entryClone.synonym = null
   141→                logger.trace("add splited entry : ({}) : {}~{}", entryClone, entryClone.start, entryClone.length)
   142→                queue.add(baseInx + addInx, entryClone)
   143→                addInx++
   144→            }
   145→            return addInx
   146→        }
