   149→        fun mergeQueueIndex(qinx: Int, typeContinuous: Int, queue: MutableList<RuleEntry>, subQueue: MutableList<RuleEntry>?): RuleEntry? {
   150→            var tc = typeContinuous
   151→            var removeInx = qinx - tc
   152→            if (removeInx < 0) {
   153→                removeInx = 0
   154→                tc--
   155→            }
   156→
   157→            if (queue[removeInx + tc - 1].type == SYMBOL) {
   158→                tc--
   159→            }
   160→
   161→            if (tc == 1) {
   162→                logger.trace("queue has only one entry. so don't merge it")
   163→                return null
   164→            }
   165→
   166→            logger.trace("queue[{}]={}", removeInx + tc - 1, queue[removeInx + tc - 1])
   167→
   168→            val entry = queue[removeInx].clone()
   169→            logger.trace("ENTRY-CLONE:{}", entry)
   170→            if (entry.type == UNIT_ALPHA) {
   171→                entry.synonym = null
   172→            }
   173→            entry.length = 0
   174→            entry.endOffset = entry.startOffset
   175→            var type = entry.type
   176→            var subEntry: RuleEntry
   177→            var nextEntry: RuleEntry?
   178→            var dummy: RuleEntry?
   179→            var remaining = tc
   180→            while (remaining > 0) {
   181→                subEntry = queue.removeAt(removeInx)
   182→                logger.trace("pop entry:{}/{}:{}[{}~{}] / {}", subEntry, subEntry.start, subEntry.length, subEntry.startOffset, subEntry.endOffset, subEntry.synonym)
   183→                if (type != subEntry.type || (type == UNIT_ALPHA && subEntry.type == UNIT_ALPHA)) {
   184→                    type = null
   185→                }
   186→                val start = subEntry.start
   187→                val length = subEntry.length
   188→                val endOffset = subEntry.endOffset
   189→                if (subQueue != null) {
   190→                    if (subEntry.type == UNIT_ALPHA) {
   191→                        logger.trace("subList:{}{}", "", subEntry.subEntry)
   192→                        if (subEntry.subEntry.size > 0) {
   193→                            var numIdx = 0
   194→                            for (e in subEntry.subEntry) {
   195→                                if (e.type == NUMBER || e.type == NUMBER_TRANS) {
   196→                                    break
   197→                                } else if (numIdx == subEntry.subEntry.size - 1) {
   198→                                    numIdx = 0
   199→                                }
   200→                                numIdx++
   201→                            }
   202→                            val number = subEntry.subEntry.removeAt(numIdx)
   203→                            subQueue.add(number)
   204→                            subEntry.start += number.length
   205→                            subEntry.length -= number.length
   206→                            subEntry.startOffset += number.length
   207→                            subEntry.type = ALPHA
   208→                            if (removeInx < queue.size &&
   209→                                queue[removeInx].also { nextEntry = it }.type == ALPHA &&
   210→                                nextEntry!!.startOffset == subEntry.endOffset) {
   211→                                dummy = subEntry.clone()
   212→                                subQueue.add(dummy)
   213→                                subEntry.length += nextEntry!!.length
   214→                                subEntry.endOffset += nextEntry!!.length
   215→                                queue.removeAt(removeInx)
   216→                                remaining--
   217→                            }
   218→                        } else {
   219→                            subEntry.type = ALPHANUM
   220→                        }
   221→                        subEntry.synonym = null
   222→                        subQueue.add(subEntry)
   223→                    } else {
   224→                        subQueue.add(subEntry)
   225→                    }
   226→                }
   227→                logger.trace("merge : {}[{}:{}/{}~{}]", subEntry, subEntry.start, subEntry.length, subEntry.startOffset, subEntry.endOffset)
   228→                logger.trace("subQueue : {}", subQueue)
   229→                entry.length = start + length - entry.start
   230→                entry.endOffset = endOffset
   231→                remaining--
   232→            }
   233→            entry.type = type
   234→            queue.add(removeInx, entry)
   235→            return entry
   236→        }
