   316→        @JvmStatic
   317→        fun modifyRuleEntry(
   318→            fullExtract: Boolean, option: AnalyzerOption, e0: RuleEntry, e1: RuleEntry?,
   319→            unitCandidate: CharVector, units: Array<CharSequence>?,
   320→            unitType: String?
   321→        ): RuleEntry? {
   322→            var resultE1 = e1
   323→            val backup = e0.clone()
   324→            if (fullExtract) {
   325→                e0.subEntry = ArrayList()
   326→                e0.subEntry.add(backup)
   327→            }
   328→
   329→            var synonyms: Array<CharSequence>? = null
   330→            if (fullExtract && units != null && option.useForQuery()) {
   331→                if (!(units.size == 1 && unitCandidate == units[0])) {
   332→                    synonyms = Array(units.size) { inx ->
   333→                        val ubuf = CharArray(e0.length + units[inx].length)
   334→                        val unitInx = CharVector.valueOf(units[inx])
   335→                        System.arraycopy(e0.buf, e0.start, ubuf, 0, e0.length)
   336→                        System.arraycopy(unitInx.array(), unitInx.offset(), ubuf,
   337→                            e0.length, units[inx].length)
   338→                        CharVector(ubuf) as CharSequence
   339→                    }
   340→                }
   341→            }
   342→
   343→            if (e0.type == NUMBER_TRANS) {
   344→                var number = e0.makeTerm(null)
   345→                number = CharVector(number.toString().replace(",", ""))
   346→                if (backup.length != number.length()) {
   347→                    val unitStr = number.toString() + unitCandidate.toString()
   348→                    resultE1 = RuleEntry(unitStr.toCharArray(), 0, unitStr.length,
   349→                        e0.startOffset, e0.endOffset + unitCandidate.length(), UNIT)
   350→                    e0.subEntry.add(0, resultE1)
   351→                    logger.trace("E0:{}/E1:{}", e0, resultE1)
   352→                }
   353→            }
   354→
   355→            if (fullExtract) {
   356→                if (e0.subEntry == null) {
   357→                    e0.subEntry = ArrayList()
   358→                }
   359→                if (synonyms != null && synonyms.isNotEmpty()) {
   360→                    e0.synonym = synonyms
   361→                }
   362→            }
   363→
   364→            e0.length += unitCandidate.length()
   365→            e0.endOffset += unitCandidate.length()
   366→
   367→            if (unitType == ALPHA) {
   368→                e0.type = UNIT_ALPHA
   369→            } else {
   370→                e0.type = UNIT
   371→            }
   372→
   373→            return resultE1
   374→        }
