   377→        fun mergeSubQueue(entry: RuleEntry, subQueue: MutableList<RuleEntry>, option: AnalyzerOption, unitDictionary: SetDictionary?) {
   378→            if (entry.type == MODEL_NAME) {
   379→                var processed = false
   380→                if (subQueue.size == 3) {
   381→                    var contCnt = 0
   382→                    val initEntry = subQueue[0].clone()
   383→                    var prevEntry: RuleEntry = initEntry
   384→                    for (cinx in 1 until subQueue.size) {
   385→                        val currentEntry = subQueue[cinx]
   386→                        if (prevEntry.startOffset + prevEntry.length != currentEntry.startOffset) {
   387→                            break
   388→                        }
   389→                        initEntry.length += currentEntry.length
   390→                        prevEntry = currentEntry
   391→                        contCnt++
   392→                    }
   393→                    if (contCnt > 0 && contCnt == subQueue.size - 1) {
   394→                        if (initEntry.length == 2) {
   395→                            val charType = getType(initEntry.buf[initEntry.start])
   396→                            val nextCharType = getType(initEntry.buf[initEntry.start + 1])
   397→                            if ((charType == ALPHA || charType == NUMBER) && (nextCharType == SYMBOL)) {
   398→                                entry.length -= 1
   399→                                entry.endOffset -= 1
   400→                                entry.type = charType
   401→                                subQueue.clear()
   402→                                processed = true
   403→                            } else if ((charType == SYMBOL) && (nextCharType == ALPHA || nextCharType == NUMBER)) {
   404→                                entry.start++
   405→                                entry.startOffset++
   406→                                entry.length--
   407→                                entry.type = nextCharType
   408→                                subQueue.clear()
   409→                                processed = true
   410→                            } else if (charType != nextCharType &&
   411→                                (charType == ALPHA || charType == NUMBER) &&
   412→                                (nextCharType == ALPHA || nextCharType == NUMBER)) {
   413→                                subQueue.clear()
   414→                                processed = true
   415→                            }
   416→                        } else if (initEntry.length == 3) {
   417→                            val charType = getType(initEntry.buf[initEntry.start])
   418→                            val nextCharType = getType(initEntry.buf[initEntry.start + 1])
   419→                            val nextNextCharType = getType(initEntry.buf[initEntry.start + 2])
   420→                            if ((charType == ALPHA || charType == NUMBER) &&
   421→                                (nextCharType == SYMBOL) &&
   422→                                (nextNextCharType == ALPHA || nextNextCharType == NUMBER)) {
   423→                                subQueue.clear()
   424→                            } else if (charType != nextCharType && nextCharType != nextNextCharType &&
   425→                                (charType == ALPHA || charType == NUMBER) &&
   426→                                (nextCharType == ALPHA || nextCharType == NUMBER) &&
   427→                                (nextNextCharType == ALPHA || nextNextCharType == NUMBER)) {
   428→                                subQueue.clear()
   429→                            }
   430→                            processed = true
   431→                        }
   432→                    }
   433→                }
   434→                if (!processed) {
   435→                    if (subQueue.size == 2) {
   436→                        val currentEntry = subQueue[0]
   437→                        val nextEntry = subQueue[1]
   438→                        if (currentEntry.length == 1 && nextEntry.length == 1) {
   439→                            subQueue.clear()
   440→                        } else if (currentEntry.type == SYMBOL) {
   441→                            entry.start += currentEntry.length
   442→                            entry.startOffset += currentEntry.length
   443→                            entry.length -= currentEntry.length
   444→                            entry.type = nextEntry.type
   445→                        } else if (nextEntry.type == SYMBOL) {
   446→                            entry.length -= nextEntry.length
   447→                            entry.endOffset -= nextEntry.length
   448→                            entry.type = currentEntry.type
   449→                        }
   450→                    } else if (subQueue.size == 3) {
   451→                        val currentEntry = subQueue[0]
   452→                        val nextEntry = subQueue[1]
   453→                        val nextNextEntry = subQueue[2]
   454→                        if (currentEntry.length == 1 && nextEntry.length == 1 && nextNextEntry.length == 1) {
   455→                            if ((currentEntry.type == ALPHA || currentEntry.type == NUMBER)
   456→                                && (nextNextEntry.type == ALPHA || nextNextEntry.type == NUMBER)) {
   457→                                if (nextEntry.type == SYMBOL) {
   458→                                    if (nextEntry.buf[nextEntry.start] != '+') {
   459→                                        subQueue.clear()
   460→                                    }
   461→                                } else if (currentEntry.type == nextNextEntry.type) {
   462→                                    currentEntry.length += nextEntry.length + nextNextEntry.length
   463→                                    currentEntry.endOffset = nextNextEntry.endOffset
   464→                                    subQueue.removeAt(2)
   465→                                    subQueue.removeAt(1)
   466→                                }
   467→                            }
   468→                        }
   469→                    }
   470→                }
   471→
   472→                var continuous = 0
   473→
   474→                logger.trace("subQueue : {}", subQueue)
   475→
   476→                for (inx in 0..subQueue.size) {
   477→                    var workingEntry: RuleEntry? = null
   478→                    if (inx < subQueue.size) {
   479→                        workingEntry = subQueue[inx]
   480→                    }
   481→                    if (workingEntry != null && workingEntry.length == 1 && (workingEntry.type == ALPHA || workingEntry.type == NUMBER)) {
   482→                        logger.trace("e0:{} / {}:{}", workingEntry, inx, continuous)
   483→                        continuous++
   484→                    } else if (continuous > 1) {
   485→                        var frontMatch = inx > 0 && (inx - continuous) > 0
   486→                        if (frontMatch) {
   487→                            val prevEntry = subQueue[inx - continuous - 1]
   488→                            if (!(prevEntry.type == SYMBOL && prevEntry.length == 1)) {
   489→                                frontMatch = false
   490→                            }
   491→                        }
   492→                        var rearMatch = inx > 0 && inx < subQueue.size
   493→                        if (rearMatch) {
   494→                            val nextEntry = subQueue[inx]
   495→                            if (!(nextEntry.type == SYMBOL && nextEntry.length == 1)) {
   496→                                rearMatch = false
   497→                            }
   498→                        }
   499→                        if (inx < subQueue.size) {
   500→                            logger.trace("inx:{}/{} / continuous:{} / fmatch:{} / rmatch:{} / entry:{}", inx, subQueue.size, continuous, frontMatch, rearMatch, subQueue[inx])
   501→                        }
   502→
   503→                        @Suppress("NAME_SHADOWING")
   504→                        var inx = inx
   505→                        if (option.useForQuery() && ((inx - continuous == 0 && rearMatch)
   506→                                    || (frontMatch && inx == subQueue.size)
   507→                                    || frontMatch && rearMatch)) {
   508→                            val pos = inx - continuous
   509→                            val currentEntry = subQueue[pos].clone()
   510→                            currentEntry.length += continuous - 1
   511→                            if (continuous < 3) {
   512→                                var subInx = 0
   513→                                while (subInx < continuous) {
   514→                                    val nextEntry = subQueue[pos + subInx]
   515→                                    subQueue.removeAt(pos + subInx)
   516→                                    currentEntry.subEntry.add(nextEntry)
   517→                                    logger.trace("remove entry : {} , C:{}/{}/{}", nextEntry, continuous, subInx, inx)
   518→                                    continuous--
   519→                                    subInx--
   520→                                    inx--
   521→                                    subInx++
   522→                                }
   523→                            }
   524→                            currentEntry.type = ALPHANUM
   525→                            currentEntry.endOffset += currentEntry.length - 1
   526→                            if (frontMatch && rearMatch) {
   527→                                subQueue.add(pos + continuous, currentEntry)
   528→                            } else if (frontMatch) {
   529→                                subQueue.add(pos + continuous, currentEntry)
   530→                            } else if (rearMatch) {
   531→                                subQueue.add(pos, currentEntry)
   532→                            }
   533→                            logger.trace("entry : {}", currentEntry)
   534→                            inx -= continuous
   535→                        }
   536→                        continuous = 0
   537→                    } else {
   538→                        continuous = 0
   539→                    }
   540→                }
