    50→                continue
    51→            }
    52→
    53→            if (currentEntry.type == UNCATEGORIZED) {
    54→                if (!userDictionary!!.contains(currentEntry.makeTerm(null))) {
    55→                    val entry = queue.removeAt(qinx)
    56→                    Entry.split(entry, queue, qinx)
    57→                    currentEntry = queue[qinx]
    58→                } else {
    59→                    currentEntry.type = HANGUL
    60→                }
    61→            }
    62→            cvTmp.init(currentEntry.buf, currentEntry.start, currentEntry.length)
    63→
    64→            if (fullExtract) {
    65→                qinx = ruleFullExtract(queue, cvTmp, currentEntry, qinx)
    66→            }
    67→            currentEntry = queue[qinx]
    68→
    69→            if (currentEntry.type == HANGUL && currentEntry.modifiable) {
    70→                if (getType(currentEntry.buf[currentEntry.start]) == NUMBER) {
    71→                    var numInx = 1
    72→                    var numberTrans = false
    73→                    while (numInx < currentEntry.length) {
    74→                        val ch = currentEntry.buf[currentEntry.start + numInx]
    75→                        val numberChar = containsChar(AVAIL_SYMBOLS_INNUMBER, ch)
