    96→                                if (qinx > 0) {
    97→                                    prevEntry = queue[qinx - 1]
    98→                                    joinable = currentEntry.start == prevEntry.start + prevEntry.length && (prevEntry.type == ALPHA || prevEntry.type == NUMBER || prevEntry.type == SYMBOL)
    99→                                }
   100→                                if (!joinable && qinx + 1 < queue.size) {
   101→                                    nextEntry = queue[qinx + 1]
   102→                                    joinable = nextEntry.start == currentEntry.start + currentEntry.length && (nextEntry.type == ALPHA || nextEntry.type == NUMBER || nextEntry.type == SYMBOL)
   103→                                }
