   134→    private fun ruleFullExtract(queue: MutableList<RuleEntry>, cvTmp: CharVector, currentEntry: RuleEntry, qinx: Int): Int {
   135→        var prevEntry: RuleEntry
   136→        var ctype = getType(currentEntry.buf[currentEntry.start + currentEntry.length - 1])
   137→        for (linx in 10 downTo 1) {
   138→            var passFlag = 0
   139→            val tmpBuf = currentEntry.buf
   140→            val tmpSt = currentEntry.start
   141→            var tmpEd: Int
   142→
   143→            if (queue.size > qinx + linx) {
   144→                prevEntry = queue[qinx + linx]
   145→                if (prevEntry.buf === tmpBuf && prevEntry.length > 0 && prevEntry.type != FULL_STRING) {
   146→                    tmpEd = prevEntry.start + prevEntry.length
   147→                    val tmpStCh = if (tmpSt > 0) tmpBuf[tmpSt - 1] else 0.toChar()
   148→                    val tmpEdCh = if (tmpEd < entry.lastPosition) tmpBuf[tmpEd] else 0.toChar()
   149→                    val tmpStCType = getType(tmpStCh)
   150→                    val tmpEdCType = getType(tmpEdCh)
   151→                    passFlag = ruleCombineEntry(queue, currentEntry, qinx, ctype, linx, passFlag, tmpSt, tmpEd, tmpStCh, tmpEdCh, tmpStCType, tmpEdCType)
   152→                    ctype = tmpEdCType
   153→                }
   154→            }
   155→
   156→            if (passFlag != 0) {
   157→                prevEntry = queue[qinx + linx]
   158→                cvTmp.init(currentEntry.buf, currentEntry.start, prevEntry.start + prevEntry.length - currentEntry.start)
   159→                passFlag = 0
   160→
   161→                if (spaceDictionary != null && spaceDictionary!!.containsKey(cvTmp)) {
   162→                    val currentTerm = CharVector()
   163→                    currentTerm.init(currentEntry.buf, currentEntry.start, currentEntry.length)
   164→                    val prevTerm = CharVector()
   165→                    prevTerm.init(prevEntry.buf, prevEntry.start, prevEntry.length)
   166→                    if (!unitDictionary!!.contains(currentTerm) && !unitDictionary!!.contains(prevTerm)) {
   167→                        passFlag = 1
   168→                    }
   169→                } else if (stopDictionary != null && stopDictionary!!.contains(cvTmp)) {
   170→                    passFlag = 2
   171→                } else if (containsDictionary(cvTmp)) {
   172→                    passFlag = 3
   173→                }
   174→
   175→                if (passFlag != 0) {
   176→                    Entry.merge(currentEntry, prevEntry, HANGUL)
   177→                    if (qinx + linx >= qinx) {
   178→                        queue.subList(qinx, qinx + linx + 1).clear()
   179→                    }
   180→                    return when (passFlag) {
   181→                        1 -> ruleSpaceDict(queue, cvTmp, currentEntry, qinx)
   182→                        2 -> { ruleStopDict(queue, currentEntry, qinx); qinx }
   183→                        else -> { queue.add(qinx, currentEntry); qinx }
   184→                    }
   185→                }
   186→            }
   187→        }
   188→        return qinx
   189→    }
