   208→    private fun ruleCombineEntry(queue: MutableList<RuleEntry>, currentEntry: RuleEntry, qinx: Int, ctype: String?, linx: Int, passFlag: Int, tmpSt: Int, tmpEd: Int, tmpStCh: Char, tmpEdCh: Char, tmpStCType: String?, tmpEdCType: String?): Int {
   209→        var nextEntry: RuleEntry
   210→        var prevEntry: RuleEntry
   211→        if ((tmpSt == 0 || (tmpStCh.code != 0 && (tmpStCh == ' ' || tmpStCType != ctype))) &&
   212→            (tmpEd == entry.lastPosition || (tmpEdCh.code != 0 && (tmpEdCh == ' ' || tmpEdCType != ctype)))) {
   213→            var flag = 1
   214→            prevEntry = currentEntry
   215→            for (tinx in 0 until linx) {
   216→                nextEntry = queue[qinx + tinx + 1]
   217→                if (nextEntry.length == 0 || nextEntry.type == FULL_STRING || nextEntry.start != prevEntry.start + prevEntry.length) {
   218→                    flag = 0
   219→                    break
   220→                }
   221→                prevEntry = nextEntry
   222→            }
   223→            return flag
   224→        }
   225→        return passFlag
   226→    }
