   228→    private fun ruleStopDict(queue: MutableList<RuleEntry>, currentEntry: RuleEntry, qinx: Int) {
   229→        currentEntry.modifiable = false
   230→        queue.add(qinx, currentEntry)
   231→    }
   232→
   233→    private fun ruleSpaceDict(queue: MutableList<RuleEntry>, cvTmp: CharVector, currentEntry: RuleEntry, qinx: Int): Int {
   234→        var prevEntry: RuleEntry
   235→        val splits = spaceDictionary!!.get(cvTmp)
   236→        var start = currentEntry.start
   237→        var startOffset = currentEntry.startOffset
   238→        for (sinx in splits!!.indices) {
   239→            val split = splits[sinx]
   240→            prevEntry = RuleEntry(currentEntry.buf, start, split.length,
   241→                startOffset, startOffset + split.length, HANGUL)
   242→            ruleStopDict(queue, prevEntry, qinx + sinx)
   243→            start += prevEntry.length
   244→            startOffset += prevEntry.length
   245→        }
   246→        return qinx + splits.size - 1
   247→    }
