    93→    private fun getRuleEntry(queue: MutableList<RuleEntry>, nextNextEntry: RuleEntry?, qinx: Int, currentEntry: RuleEntry, nextEntry: RuleEntry, unitCandidate: CharVector, findInx: Int): RuleEntry? {
