   107→        if (isAllMatchTerm(queue, qinx, nextEntry, unitCandidate, findInx)) {
   108→            if (isAlphaWithUnit(typePrev, unitType, tempch1)) {
   109→                processUnitSynonym(queue, qinx, currentEntry, nextEntry, unitCandidate, findInx, unitType, units)
   110→            }
