   127→    private fun getXNextEntry(queue: MutableList<RuleEntry>, nextNextEntry: RuleEntry?, qinx: Int): RuleEntry? {
   128→        return if (qinx + 2 < queue.size) {
   129→            queue[qinx + 2]
   130→        } else {
   131→            nextNextEntry
   132→        }
   133→    }
