   135→    private fun processUnitSynonym(queue: MutableList<RuleEntry>, qinx: Int, currentEntry: RuleEntry, nextEntry: RuleEntry, unitCandidate: CharVector, findInx: Int, unitType: String?, units: Array<CharSequence>?) {
   136→        Entry.modifyRuleEntry(fullExtract, option, currentEntry, nextEntry, unitCandidate, units, unitType)
   137→        logger.trace("currentEntry:{} / SYN:{}", currentEntry, currentEntry.synonym)
   138→        var isNumberTransEntry = false
   139→        for (e in currentEntry.subEntry) {
   140→            if (e.type == NUMBER_TRANS) {
   141→                isNumberTransEntry = true
   142→                break
   143→            }
   144→        }
   145→        var fi = findInx
   146→        while (fi >= 1) {
   147→            if (!isNumberTransEntry && (currentEntry.type != UNIT)) {
   148→                queue.removeAt(qinx + fi)
   149→            } else if (option.useForQuery()) {
   150→                queue.removeAt(qinx + fi)
   151→            }
   152→            fi--
   153→        }
