   165→    private fun isAllMatchTerm(queue: MutableList<RuleEntry>, qinx: Int, nextEntry: RuleEntry, unitCandidate: CharVector, findInx: Int): Boolean {
   166→        return (findInx == 1 && unitCandidate.length() == nextEntry.length) ||
   167→                (findInx > 1 && (qinx + findInx) < queue.size && unitCandidate.length() ==
   168→                        queue[qinx + findInx].endOffset - nextEntry.startOffset)
