   171→    private fun findUnitDictionary(key: CharVector, type: String?): Boolean {
   172→        key.ignoreCase()
   173→        if (isEquals(type, ALPHA) || isEquals(type, SYMBOL)) {
   174→            if (key.length() > MAX_UNIT_LENGTH) {
   175→                key.length(MAX_UNIT_LENGTH)
   176→            }
   177→            if (checkUnitDictionary(key)) return true
   178→            key.length(key.length() - 1)
   179→            return false
   180→        } else {
   181→            return isContainUnitDictionary(key)
   182→        }
   183→    }
   184→
   185→    private fun checkUnitDictionary(key: CharVector): Boolean {
   186→        var len = key.length()
   187→        while (len >= 0) {
   188→            key.length(len)
   189→            if (isContainUnitDictionary(key)) return true
   190→            len--
   191→        }
   192→        return false
   193→    }
   194→
   195→    private fun isContainUnitDictionary(key: CharVector): Boolean {
   196→        return unitDictionary != null && unitDictionary!!.set().contains(key)
   197→    }
   198→}
