     9→class RuleFour(
    10→    entry: Entry, fullExtract: Boolean, option: AnalyzerOption,
    11→    unitDictionary: SetDictionary?
    12→) : Rule(entry, fullExtract, option) {
    13→
    14→    init {
    15→        this.unitDictionary = unitDictionary
    16→    }
    17→
    18→    override fun apply(queue: MutableList<RuleEntry>) {
    19→        val remainOption = ContinuousOption()
    20→
    21→        var qinx = 0
    22→        while (qinx < queue.size) {
    23→            val currentEntry = initEntry(queue, remainOption, qinx)
    24→
    25→            if (remainOption.isAlphaNum || isSymbolEntry(currentEntry) || isUnitAlphaEntry(currentEntry) || isUnitEntry(currentEntry)) {
    26→                if (qinx == 0) {
    27→                    // NOP
    28→                } else if (qinx < queue.size) {
    29→                    val prevEntry = queue[qinx - 1]
    30→
    31→                    if (currentEntry.length == 0 || prevEntry.length == 0) {
    32→                        breakContinuous(remainOption, remainOption.typeContinuous)
    33→                    } else if (isConnected(prevEntry, currentEntry) && (
    34→                                (
    35→                                    isNotSymbol(currentEntry) && ((remainOption.isAlphaNumPrev) || isUnitAlphaEntry(prevEntry) || (isSymbolEntry(prevEntry) && remainOption.typeContinuous > 0))
    36→                                    && !(isAlphaEntry(prevEntry) && isUnitEntry(currentEntry))
    37→                                ) ||
    38→                                (
    39→                                    isSymbolEntry(currentEntry) && (remainOption.isAlphaNumPrev || (isUnitAlphaEntry(prevEntry) && remainOption.typeContinuous > 0)) && currentEntry.length == 1 && containsChar(AVAIL_SYMBOLS_CONNECTOR, currentEntry.buf[currentEntry.start])
    40→                                ) ||
    41→                                (
    42→                                    isUnitAlphaEntry(currentEntry) && prevEntry.length == 1 && prevEntry.buf[prevEntry.start] == AVAIL_SYMBOLS[0]
    43→                                ) ||
    44→                                (
    45→                                    isSymbolEntry(currentEntry) && (remainOption.isAlphaNumPrev || (isUnitAlphaEntry(prevEntry) && remainOption.typeContinuous >= 0)) && currentEntry.length == 1 && currentEntry.buf[currentEntry.start] == AVAIL_SYMBOLS[0]
    46→                                ) ||
    47→                                (
    48→                                    !option.useForQuery() && isUnitAlphaEntry(currentEntry) && prevEntry.length == 1 && prevEntry.buf[prevEntry.start] == AVAIL_SYMBOLS[2]
    49→                                ) ||
    50→                                (
    51→                                    !option.useForQuery() && isSymbolEntry(currentEntry) && (remainOption.isAlphaNumPrev || (isUnitAlphaEntry(prevEntry) && remainOption.typeContinuous >= 0)) && currentEntry.length == 1 && currentEntry.buf[currentEntry.start] == AVAIL_SYMBOLS[2]
    52→                                )
    53→                            )
    54→                    ) {
    55→                        remainOption.typeContinuous++
    56→                        remainOption.isContinue = true
    57→                    } else {
    58→                        breakContinuous(remainOption, remainOption.typeContinuous)
    59→                    }
    60→                }
    61→            } else {
    62→                breakContinuous(remainOption, remainOption.typeContinuous)
    63→            }
    64→            if (logger.isTraceEnabled) {
    65→                logger.trace("qinx:{} / type:{} / typePrev:{} / typeCont:{} / continue:{} / e0:{} / char:[{}]:{}", qinx, remainOption.type, remainOption.typePrev, remainOption.typeContinuous, remainOption.isContinue, currentEntry, currentEntry.buf[currentEntry.start], containsChar(AVAIL_SYMBOLS_INNUMBER, currentEntry.buf[currentEntry.start]))
    66→            }
    67→
    68→            if (remainOption.type == UNIT_ALPHA && remainOption.typePrev == UNIT_ALPHA) {
    69→                if (option.useForQuery()) {
    70→                    val prevEntry = queue[qinx - 1]
    71→                    if (isConnected(prevEntry, currentEntry)) {
    72→                        logger.trace("model name cancel 1")
    73→                        cancelModelName(queue, remainOption, qinx, currentEntry)
    74→                    } else {
    75→                        logger.trace("model name break !")
    76→                        remainOption.isContinue = false
    77→                        remainOption.typePrev = null
    78→                    }
    79→                } else {
    80→                    logger.trace("model name break !")
    81→                    remainOption.isContinue = false
    82→                    remainOption.typePrev = null
    83→                }
    84→            } else if (remainOption.type == SYMBOL && currentEntry.length == 1) {
    85→                qinx = ruleSymbolEntry(queue, remainOption, qinx, currentEntry)
    86→            } else if (remainOption.type == UNIT_ALPHA) {
    87→                ruleUnitAlphaEntry(queue, remainOption, qinx, currentEntry)
    88→            }
    89→            if (remainOption.isContinue) {
    90→                logger.trace("continue..")
    91→                qinx++
    92→                continue
    93→            }
    94→
    95→            if (remainOption.typeContinuousMerge > 0) {
    96→                qinx = combineUsedModelNameTerm(queue, remainOption, qinx, currentEntry)
    97→            }
    98→            remainOption.typeContinuousMerge = 0
    99→            qinx++
   100→        }
   101→        if (remainOption.typeContinuous > 0 && remainOption.typeContinuousMerge == 0) {
   102→            remainOption.typeContinuousMerge = remainOption.typeContinuous
   103→        }
   104→        if (remainOption.typeContinuousMerge > 0) {
   105→            ruleRemainTerm(queue, remainOption)
   106→        }
