   108→    }
   109→
   110→    private fun ruleRemainTerm(queue: MutableList<RuleEntry>, remainOption: ContinuousOption) {
   111→        remainOption.typeContinuousMerge++
   112→        if (remainOption.type == SYMBOL) {
   113→            queue.removeAt(queue.size - 1)
   114→            remainOption.typeContinuousMerge--
   115→        }
   116→        if (remainOption.typeContinuousMerge > 1) {
   117→            var subQueue: MutableList<RuleEntry>? = null
   118→            if (fullExtract) {
   119→                subQueue = ArrayList()
   120→            }
   121→            logger.trace("merging.. {} / {} / {}", remainOption.typeContinuousMerge, queue, subQueue)
   122→            val entry: RuleEntry? = if (!option.useForQuery()) {
   123→                Entry.mergeQueueIndex(queue.size, remainOption.typeContinuousMerge, queue, subQueue)
   124→            } else {
   125→                Entry.mergeQueueQuery(queue.size, remainOption.typeContinuousMerge, queue, subQueue)
   126→            }
   127→
   128→            if (entry != null) {
   129→                if (entry.type == null) { entry.type = MODEL_NAME }
   130→                logger.trace("subQueue:{}", subQueue)
   131→                if (fullExtract) {
   132→                    logger.trace("## MERGE_2 : {} : {}", entry, subQueue)
   133→                    Entry.mergeSubQueue(entry, subQueue!!, option, unitDictionary)
   134→                    if (subQueue.size > 1) {
   135→                        entry.subEntry = subQueue
   136→                    }
   137→                    logger.trace("entry:{} / subQueue:{}", entry, entry.subEntry)
   138→                }
   139→            }
   140→        }
   141→    }
