   143→    private fun combineUsedModelNameTerm(queue: MutableList<RuleEntry>, remainOption: ContinuousOption, qinx: Int, currentEntry: RuleEntry): Int {
   144→        var idx = qinx
   145→        remainOption.typeContinuousMerge++
   146→        if (remainOption.type == SYMBOL) {
   147→            if (!(currentEntry.length == 1 && containsChar(AVAIL_SYMBOLS_STANDALONE, currentEntry.buf[currentEntry.start]))) {
   148→                queue.removeAt(idx)
   149→            }
   150→        }
   151→
   152→        if (remainOption.typeContinuousMerge > 1) {
   153→            var subQueue: MutableList<RuleEntry>? = null
   154→            if (fullExtract) {
   155→                subQueue = ArrayList()
   156→            }
   157→            logger.trace("merging..qinx:{} / tcont:{}", idx, remainOption.typeContinuousMerge)
   158→            val entry: RuleEntry? = if (!option.useForQuery()) {
   159→                Entry.mergeQueueIndex(idx, remainOption.typeContinuousMerge, queue, subQueue)
   160→            } else {
   161→                Entry.mergeQueueQuery(idx, remainOption.typeContinuousMerge, queue, subQueue)
   162→            }
   163→
   164→            if (entry != null) {
   165→                if (entry.type == null) { entry.type = MODEL_NAME }
   166→                logger.trace("qinx:{} / typeContinuousMerge:{} / overIndex:{}", idx, remainOption.typeContinuousMerge, remainOption.overIndex)
   167→                idx -= remainOption.typeContinuousMerge
   168→                logger.trace("qinx:{}", idx)
   169→                idx -= remainOption.overIndex
   170→                if (fullExtract) {
   171→                    logger.trace("## MERGE_1 : {} : {}", entry, subQueue)
   172→                    Entry.mergeSubQueue(entry, subQueue!!, option, unitDictionary)
   173→                    if (subQueue.size > 1) {
   174→                        entry.subEntry = subQueue
   175→                    }
   176→                    logger.trace("entry:{} / subQueue:{}", entry, entry.subEntry)
   177→                    logger.trace("## Q[{}] : {}", idx, queue)
   178→                }
   179→            }
   180→        }
   181→        return idx
   182→    }
