   184→    private fun ruleUnitAlphaEntry(queue: MutableList<RuleEntry>, remainOption: ContinuousOption, qinx: Int, currentEntry: RuleEntry) {
   185→        var prevEntry: RuleEntry? = null
   186→        var nextEntry: RuleEntry? = null
   187→        if (qinx > 0) {
   188→            prevEntry = queue[qinx - 1]
   189→        }
   190→        if (qinx + 1 < queue.size) {
   191→            nextEntry = queue[qinx + 1]
   192→        }
   193→        if (prevEntry != null && (currentEntry.start != prevEntry.start + prevEntry.length)) {
   194→            remainOption.typeContinuous = 0
   195→            remainOption.isContinue = false
   196→        } else if (prevEntry != null && nextEntry != null
   197→            && (isSymbolEntry(prevEntry) && !(isAlphaEntry(nextEntry) || isNumberEntry(nextEntry))
   198→                    || isSymbolEntry(nextEntry) && !(isAlphaEntry(prevEntry) || isNumberEntry(prevEntry)))
   199→        ) {
   200→            if (!(prevEntry.buf[prevEntry.start] == '-' || nextEntry.buf[nextEntry.start] == '-')) {
   201→                currentEntry.modifiable = false
   202→                if (remainOption.typeContinuous > 0) {
   203→                    logger.trace("model name cancel 6")
   204→                    breakContinuous(remainOption, remainOption.typeContinuous - 1)
   205→                } else {
   206→                    remainOption.typeContinuous = 0
   207→                    remainOption.isContinue = true
   208→                }
   209→            } else {
   210→                remainOption.isContinue = false
   211→            }
   212→        }
   213→    }
   214→
   215→    private fun ruleSymbolEntry(queue: MutableList<RuleEntry>, remainOption: ContinuousOption, qinx: Int, currentEntry: RuleEntry): Int {
   216→        var idx = qinx
   217→        if (currentEntry.buf[currentEntry.start] == '/' && option.useForQuery()) {
   218→            if (idx > 0 && idx + 1 < queue.size) {
   219→                val prevEntry = queue[idx - 1]
   220→                val nextEntry = queue[idx + 1]
   221→                if (isConnected(prevEntry, currentEntry) && isConnected(currentEntry, nextEntry)
   222→                    && (isNumberEntry(prevEntry) && isNumberEntry(nextEntry))) {
   223→                    if (remainOption.typeContinuous < 2) {
   224→                        logger.trace("model name cancel 3")
   225→                        idx = cancelModelName(queue, remainOption, idx, prevEntry, nextEntry)
   226→                    }
   227→                }
   228→            }
   229→        } else if (currentEntry.buf[currentEntry.start] == '+' && option.useForQuery()) {
   230→            if (idx > 0 && idx + 1 < queue.size) {
   231→                val prevEntry = queue[idx - 1]
   232→                val nextEntry = queue[idx + 1]
   233→                if (isConnected(prevEntry, currentEntry) && isConnected(currentEntry, nextEntry)) {
   234→                    logger.trace("model name cancel 4 / {}:{}", remainOption.typeContinuous, remainOption.typeContinuousMerge)
   235→                    cancelModelName(remainOption, prevEntry, nextEntry)
   236→                }
   237→            }
   238→        }
   239→        return idx
   240→    }
