   242→    private fun cancelModelName(queue: MutableList<RuleEntry>, remainOption: ContinuousOption, qinx: Int, currentEntry: RuleEntry) {
   243→        currentEntry.modifiable = false
   244→        queue[qinx - 1].modifiable = false
   245→        remainOption.typeContinuous = 0
   246→        remainOption.typeContinuousMerge = 0
   247→        remainOption.isContinue = true
   248→    }
   249→
   250→    private fun cancelModelName(queue: MutableList<RuleEntry>, remainOption: ContinuousOption, qinx: Int, prevEntry: RuleEntry, nextEntry: RuleEntry): Int {
   251→        prevEntry.modifiable = false
   252→        nextEntry.modifiable = false
   253→        queue.removeAt(qinx)
   254→        remainOption.typeContinuous = 0
   255→        remainOption.typeContinuousMerge = 0
   256→        remainOption.isContinue = false
   257→        return qinx - 1
   258→    }
   259→
   260→    private fun cancelModelName(remainOption: ContinuousOption, prevEntry: RuleEntry, nextEntry: RuleEntry) {
   261→        if (remainOption.isContinue && remainOption.typeContinuous != 0 && remainOption.typeContinuousMerge == 0) {
   262→            prevEntry.modifiable = false
   263→            nextEntry.modifiable = false
   264→            breakContinuous(remainOption, remainOption.typeContinuous)
   265→        }
   266→        remainOption.overIndex = 1
   267→    }
   268→
   269→    private fun breakContinuous(remainOption: ContinuousOption, typeContinuous: Int) {
   270→        remainOption.typeContinuousMerge = typeContinuous
   271→        remainOption.typeContinuous = 0
   272→        remainOption.isContinue = false
   273→    }
   274→
   275→    private fun initEntry(queue: MutableList<RuleEntry>, remainOption: ContinuousOption, qinx: Int): RuleEntry {
   276→        remainOption.typePrev = remainOption.type
   277→        val currentEntry = queue[qinx]
   278→        val cv = currentEntry.makeTerm(null)
   279→        if (currentEntry.type != FULL_STRING && getType(cv.charAt(0)) == ALPHA && (option.useForQuery() || (!option.useForQuery() && currentEntry.type != UNIT))) {
   280→            if (getTermType(cv) == ALPHA) {
   281→                currentEntry.type = ALPHA
   282→            }
   283→        }
   284→        remainOption.type = currentEntry.type
   285→        remainOption.isContinue = true
   286→        remainOption.typeContinuousMerge = 0
   287→        remainOption.overIndex = 0
   288→
   289→        if (currentEntry.type == FULL_STRING) {
   290→            remainOption.typeContinuousMerge = remainOption.typeContinuous
   291→            remainOption.typeContinuous = 0
   292→        }
   293→
   294→        if (logger.isTraceEnabled) {
   295→            logger.trace("qinx:{} / type:{} / typePrev:{} / typeCont:{} / e0:{} / char:[{}]:{}", qinx, remainOption.type, remainOption.typePrev, remainOption.typeContinuous, currentEntry, currentEntry.buf[currentEntry.start], containsChar(AVAIL_SYMBOLS_INNUMBER, currentEntry.buf[currentEntry.start]))
   296→        }
   297→
   298→        remainOption.isAlphaNumPrev = remainOption.isAlphaNum
   299→        remainOption.isAlphaNum = currentEntry.type == ALPHA || currentEntry.type == NUMBER || currentEntry.type == NUMBER_TRANS
   300→        return currentEntry
   301→    }
   302→
   303→    internal class ContinuousOption {
   304→        var typeContinuous: Int = 0
   305→        var typeContinuousMerge: Int = 0
   306→        var overIndex: Int = 0
   307→        var isContinue: Boolean = false
   308→        var isAlphaNum: Boolean = false
   309→        var isAlphaNumPrev: Boolean = false
   310→        var typePrev: String? = null
   311→        var type: String? = null
   312→    }
   313→}
