     6→class RuleTwo(entry: Entry, fullExtract: Boolean, option: AnalyzerOption)
     7→    : Rule(entry, fullExtract, option) {
     8→
     9→    override fun apply(queue: MutableList<RuleEntry>) {
    10→        var qinx = 0
    11→        while (qinx < queue.size) {
    12→            val currentEntry = queue[qinx]
    13→
    14→            if (isFullStringEntry(currentEntry)) {
    15→                qinx++
    16→                continue
    17→            }
    18→
    19→            if (existNextNextIndex(queue, qinx)) {
    20→                val nextEntry = queue[qinx + 1]
    21→                val nextNextEntry = queue[qinx + 2]
    22→
    23→                if (isChangeableNumber(currentEntry, nextEntry, nextNextEntry)) {
    24→                    val cloneEntry = currentEntry.clone()
    25→                    currentEntry.length += nextEntry.length + nextNextEntry.length
    26→                    currentEntry.endOffset = currentEntry.startOffset + currentEntry.length
    27→
    28→                    if (isNumberPattern(currentEntry)) {
    29→                        qinx = changeTransNumber(queue, qinx, currentEntry)
    30→                        qinx++
    31→                        continue
    32→                    } else {
    33→                        restoreEntry(currentEntry, cloneEntry)
    34→                    }
    35→                }
    36→            }
    37→
    38→            if (existNextIndex(queue, qinx)) {
    39→                qinx = modifyEtc(queue, qinx, currentEntry)
    40→            }
    41→            qinx++
    42→        }
    43→        logger.trace("2nd process complete / queue:{}", queue)
    44→    }
    45→
    46→    private fun modifyEtc(queue: MutableList<RuleEntry>, qinx: Int, currentEntry: RuleEntry): Int {
    47→        val nextEntry = queue[qinx + 1]
    48→        if (isConnectEntry(currentEntry, nextEntry)) {
    49→            return ruleAlterType(queue, qinx, currentEntry, nextEntry)
    50→        }
    51→        return qinx
    52→    }
    53→
    54→    private fun ruleAlterType(queue: MutableList<RuleEntry>, qinx: Int, currentEntry: RuleEntry, nextEntry: RuleEntry): Int {
    55→        if (isAlphaEntry(currentEntry) && isAlphaEntry(nextEntry)) {
    56→            setEntryType(queue, qinx, ALPHA)
    57→        } else if (isNumberEntry(currentEntry) && isNumberEntry(nextEntry)) {
    58→            setEntryType(queue, qinx, NUMBER)
    59→        } else if (isJapanOrChina(currentEntry, nextEntry)) {
    60→            return setEntryTypeJapanese(queue, qinx, currentEntry, nextEntry)
    61→        }
    62→        return qinx
    63→    }
    64→
    65→    private fun setEntryTypeJapanese(queue: MutableList<RuleEntry>, qinx: Int, currentEntry: RuleEntry, nextEntry: RuleEntry): Int {
    66→        currentEntry.length += nextEntry.length
    67→        currentEntry.endOffset = nextEntry.endOffset
    68→        currentEntry.type = JAPANESE
    69→        queue.removeAt(qinx + 1)
    70→        return qinx - 1
    71→    }
    72→
    73→    private fun isJapanOrChina(currentEntry: RuleEntry, nextEntry: RuleEntry): Boolean {
    74→        return isJapanese(currentEntry) && isJapanese(nextEntry)
    75→                || (isChinese(currentEntry) && isChinese(nextEntry))
    76→                || (isJapanese(currentEntry) && isChinese(nextEntry))
    77→    }
    78→
    79→    private fun setEntryType(queue: MutableList<RuleEntry>, qinx: Int, type: String?) {
    80→        val currentEntry = Entry.mergeQueueQuery(qinx + 2, 2, queue, null)
    81→        if (currentEntry != null) {
    82→            currentEntry.type = type
    83→        }
    84→    }
    85→
    86→    private fun isNumberPattern(currentEntry: RuleEntry): Boolean {
    87→        return PTN_NUMBER.containsMatchIn(currentEntry.makeTerm(null))
    88→    }
    89→
    90→    private fun isConnectEntry(currentEntry: RuleEntry, nextEntry: RuleEntry): Boolean {
    91→        return isConnected(currentEntry, nextEntry) && currentEntry.length > 0 && nextEntry.length > 0
    92→    }
    93→
    94→    private fun restoreEntry(currentEntry: RuleEntry, cloneEntry: RuleEntry) {
    95→        currentEntry.length = cloneEntry.length
    96→        currentEntry.endOffset = cloneEntry.endOffset
    97→    }
    98→
    99→    private fun changeTransNumber(queue: MutableList<RuleEntry>, qinx: Int, currentEntry: RuleEntry): Int {
   100→        currentEntry.type = NUMBER_TRANS
   101→        queue.removeAt(qinx + 2)
   102→        queue.removeAt(qinx + 1)
   103→        return qinx - 1
   104→    }
   105→
   106→    private fun isChangeableNumber(currentEntry: RuleEntry, nextEntry: RuleEntry, nextNextEntry: RuleEntry): Boolean {
   107→        return isEntryType(currentEntry, NUMBER, NUMBER_TRANS)
   108→                && isSymbolEntry(nextEntry) && nextEntry.length == 1
   109→                && isNumberEntry(nextNextEntry)
   110→                && isConnected(currentEntry, nextEntry)
   111→                && isConnected(nextEntry, nextNextEntry)
   112→                && isAvailSymbolChar(nextEntry.buf[nextEntry.start])
   113→    }
   114→
   115→    private fun isAvailSymbolChar(c: Char): Boolean {
   116→        return containsChar(AVAIL_SYMBOLS_INNUMBER, c)
   117→    }
   118→}
