    64→    private fun doSegment(): ExtractedEntry? {
    65→        val cv = CharVector(source, offset, length)
    66→        if (length == 1) {
    67→            val tag = koreanDict.find(cv)
    68→            if (tag != null) {
    69→                return ExtractedEntry(length - 1, length, tag[0], offset)
    70→            }
    71→            if (isDigit(cv)) {
    72→                return ExtractedEntry(length - 1, length, TagProb.DIGIT, offset)
    73→            } else if (isSymbol(cv)) {
    74→                return ExtractedEntry(length - 1, length, TagProb.SYMBOL, offset)
    75→            }
    76→            return ExtractedEntry(length - 1, length, TagProb.UNK, offset)
    77→        }
    78→        val tag = koreanDict.find(cv)
    79→        if (tag != null) {
    80→            return ExtractedEntry(length - 1, length, tag[0], offset)
    81→        }
    82→        val start = length - 1
    83→        for (row in start downTo 0) {
    84→            for (column in row + 1 downTo 1) {
    85→                cv.init(offset + row - column + 1, column)
    86→                var tagList: List<TagProb>?
    87→                var isAlpha = false
    88→                if (isDigit(cv)) {
    89→                    tabular[row][column] = PosTagProbEntry(TagProb.DIGIT)
    90→                    status[row]++
    91→                } else if (isSymbol(cv)) {
    92→                    tabular[row][column] = PosTagProbEntry(TagProb.SYMBOL)
    93→                    status[row]++
    94→                } else {
    95→                    if (isAlpha(cv)) {
    96→                        if (column == 1) {
    97→                            tabular[row][column] = PosTagProbEntry(TagProb.ALPHA)
    98→                            continue
    99→                        }
   100→                        isAlpha = true
   101→                    }
   102→                    tagList = koreanDict.find(cv)
   103→                    if (tagList != null) {
   104→                        if (column == length) {
   105→                            return ExtractedEntry(row, column, tagList[0], offset)
   106→                        }
   107→                        var chainedEntry: PosTagProbEntry? = null
   108→                        for (i in tagList.indices) {
   109→                            val tagProb = tagList[i]
   110→                            if (i == 0) {
   111→                                chainedEntry = PosTagProbEntry(tagProb)
   112→                                tabular[row][column] = chainedEntry
   113→                            } else {
   114→                                chainedEntry = chainedEntry!!.next(tagProb)
   115→                            }
   116→                        }
   117→                        status[row]++
   118→                    } else {
   119→                        if (isAlpha) {
   120→                            tabular[row][column] = PosTagProbEntry(TagProb.ALPHA)
   121→                        } else {
   122→                            tabular[row][column] = null
   123→                        }
   124→                    }
   125→
   126→                    if (column < 3) {
   127→                        if (josaSet.contains(cv)) {
   128→                            val entry = PosTagProbEntry(TagProb.JOSA)
   129→                            if (tabular[row][column] == null) {
   130→                                tabular[row][column] = entry
   131→                            } else {
   132→                                entry.next = tabular[row][column]
   133→                                tabular[row][column] = entry
   134→                            }
   135→                            status[row]++
   136→                        }
   137→                    }
   138→                }
   139→            }
   140→        }
   141→        return null
   142→    }
