   144→    private fun isUnicode(buffer: CharArray, offset: Int, length: Int): Boolean {
   145→        for (inx in 0 until length) {
   146→            val ch = buffer[offset + inx]
   147→            if (ch.code > 127) {
   148→                return true
   149→            }
   150→        }
   151→        return false
   152→    }
   153→
   154→    private fun isDigit(cv: CharVector): Boolean {
   155→        for (i in 0 until cv.length()) {
   156→            val ch = cv.charAt(i)
   157→            if (ch < '0' || ch > '9') {
   158→                return false
   159→            }
   160→        }
   161→        return true
   162→    }
   163→
   164→    private fun isAlpha(cv: CharVector): Boolean {
   165→        for (i in 0 until cv.length()) {
   166→            val ch = cv.charAt(i)
   167→            if (!((ch in 'a'..'z') || (ch in 'A'..'Z'))) {
   168→                return false
   169→            }
   170→        }
   171→        return true
   172→    }
   173→
   174→    private fun isSymbol(cv: CharVector): Boolean {
   175→        for (i in 0 until cv.length()) {
   176→            val chInt = cv.charAt(i).code
   177→            if (Character.isLetterOrDigit(chInt)) {
   178→                return false
   179→            }
   180→        }
   181→        return true
   182→    }
