   184→    private fun makeResult() {
   185→        var headRow = -1
   186→        for (row in length - 1 downTo 0) {
   187→            if (status[row] > 0) {
   188→                headRow = row
   189→                break
   190→            }
   191→        }
   192→
   193→        try {
   194→            if (headRow == -1) {
   195→                addResult(ExtractedEntry(length - 1, length, TagProb.UNK, offset))
   196→                return
   197→            }
   198→            if (headRow < length - 1) {
   199→                val tail = ExtractedEntry(length - 1, length - 1 - headRow, TagProb.UNK, offset)
   200→                connectAllTo(headRow, tail)
   201→            } else {
   202→                connectAllTo(headRow, null)
   203→            }
   204→            var tail: ExtractedEntry?
   205→            while (queue.poll().also { tail = it } != null) {
   206→                val t = tail!!
   207→                val connectRow = t.row() - t.column()
   208→                if (status[connectRow] > 0) {
   209→                    connectAllTo(connectRow, t)
   210→                } else {
   211→                    connectTo(null, connectRow, -1, t)
   212→                }
   213→            }
   214→        } catch (e: AnalyzeExceedException) {
   215→            logger.debug("Analyze exceed : " + e.message)
   216→        }
   217→    }
