   219→    @Throws(AnalyzeExceedException::class)
   220→    private fun connectAllTo(headRow: Int, tail: ExtractedEntry?): Int {
   221→        val rowData = tabular[headRow]
   222→        var found = 0
   223→        for (headColumn in headRow + 1 downTo 1) {
   224→            if (rowData[headColumn] != null) {
   225→                val tagEntry = rowData[headColumn]!!
   226→                entryStringer.set(tagEntry, source, headRow, headColumn, offset)
   227→                if (tagEntry.tagProb!!.posTag() != PosTag.ALPHA) {
   228→                    connectTo(tagEntry, headRow, headColumn, tail)
   229→                    found++
   230→                }
   231→            }
   232→            if (found >= status[headRow]) {
   233→                break
   234→            }
   235→        }
   236→        if (!isUnicode) {
   237→            var inx = 0
   238→            while (inx < result.size) {
   239→                if (result[inx].last().posTag() == PosTag.UNK) {
   240→                    result.removeAt(inx)
   241→                    inx--
   242→                }
   243→                inx++
   244→            }
   245→        }
   246→        return found
   247→    }
