   249→    @Throws(AnalyzeExceedException::class)
   250→    private fun connectTo(headTagEntry: PosTagProbEntry?, headRow: Int, headColumn: Int, tail: ExtractedEntry?): Int {
   251→        var currentEntry = headTagEntry
   252→        if (tail == null) {
   253→            var found = 0
   254→            while (currentEntry != null) {
   255→                val headEntry = ExtractedEntry(headRow, headColumn, currentEntry.get()!!, offset)
   256→                if (headEntry.row() - headEntry.column() < 0) {
   257→                    addResult(headEntry)
   258→                } else {
   259→                    addQueue(headEntry)
   260→                }
   261→                currentEntry = currentEntry.next
   262→                found++
   263→            }
   264→            return found
   265→        }
   266→
   267→        if (currentEntry == null) {
   268→            for (column in 1..headRow + 1) {
   269→                val row2 = headRow - column
   270→                if (row2 < 0 || status[row2] > 0) {
   271→                    // 2014-1-27처리..
   272→                }
   273→            }
   274→            return 1
   275→        }
   276→
   277→        var found = 0
   278→        while (currentEntry != null) {
   279→            if (isConnectableByRule(currentEntry.get()!!, headRow, headColumn, tail)) {
   280→                val newTail = modifyAndConnect(currentEntry.get()!!, headRow, headColumn, tail)
   281→                if (newTail != null) {
   282→                    if (newTail.row() - newTail.column() < 0) {
   283→                        addResult(newTail)
   284→                    } else {
   285→                        addQueue(newTail)
   286→                    }
   287→                    found++
   288→                }
   289→            }
   290→            currentEntry = currentEntry.next
   291→        }
   292→        return found
   293→    }
