   353→                        inx - offset,
   354→                        pptype != null && (pptype != ALPHA && pptype != NUMBER),
   355→                        inx < buffer.size && ptype == SYMBOL && buffer[inx] != '&',
   356→                        type != null, pptype != null,
   357→                        inx < buffer.size && ptype == SYMBOL && buffer[inx] != '&',
