   361→                            && (inx < buffer.size && ptype == SYMBOL && buffer[inx] != '&')
   362→                            && (type != null))
   363→                    || ((pptype != null) && (inx < buffer.size && ptype == SYMBOL && buffer[inx] != '&')
   364→                            && (type != null && (type != ALPHA && type != NUMBER)))) {
   365→                    logger.trace("LENGTH:{} / {}", len - offset, tabular.size)
