   410→    fun extract(): ExtractedEntry {
   411→        tabularStringer.set(tabular, source, status, length, offset)
   412→        ExtractedEntry.source = source
   413→        val e = extract0()!!
   414→        var last = e.last()
   415→        while (remnantLength > 0) {
   416→            val len = Math.min(tabular.size, remnantLength)
   417→            setInput0(source, remnantOffset, len)
   418→            val r = extract0()
   419→            if (r != null) {
   420→                if (!(last.offset() + last.column() > r.offset())) {
   421→                    last.next(r)
   422→                    last = r.last()
   423→                }
   424→            }
   425→            remnantOffset += len
   426→            remnantLength -= len
   427→        }
   428→        return e
   429→    }
