   474→    protected open fun isConnectableByRule(headTagProb: TagProb, headRow: Int, headColumn: Int, tail: ExtractedEntry): Boolean {
   475→        if (headTagProb.posTag() == PosTag.DIGIT && tail.tagProb().posTag() == PosTag.DIGIT) {
   476→            return false
   477→        }
   478→        if (headTagProb.posTag() == PosTag.ALPHA && tail.tagProb().posTag() == PosTag.ALPHA) {
   479→            return false
   480→        }
   481→        if (headTagProb.posTag() == PosTag.SYMBOL && tail.tagProb().posTag() == PosTag.SYMBOL) {
   482→            return false
   483→        }
   484→        if (headTagProb.posTag() != PosTag.ALPHA && headTagProb.posTag() != PosTag.DIGIT && headTagProb.posTag() != PosTag.SYMBOL) {
   485→            if (tail.tagProb().posTag() == PosTag.J && tail.column() == 1) {
   486→                val ch = source[offset + tail.row() - tail.column() + 1]
   487→                if (ch == '\uC740' || ch == '\uC774' || ch == '\uC744' || ch == '\uACFC') {
   488→                    if (!MorphUtil.hasLastElement(source[offset + headRow])) {
   489→                        return false
   490→                    }
   491→                } else if (ch == '\uB294' || ch == '\uAC00' || ch == '\uB97C' || ch == '\uC640') {
   492→                    if (MorphUtil.hasLastElement(source[offset + headRow])) {
   493→                        return false
   494→                    }
   495→                }
   496→            }
   497→        }
   498→
   499→        if (headColumn == 1 && tail.column() == 1 && headTagProb.posTag() != PosTag.J && tail.posTag() != PosTag.J) {
   500→            if (tabular[tail.row()][tail.column() + headColumn] != null) {
   501→                return false
   502→            }
   503→        }
   504→        return true
   505→    }
