   507→    protected open fun modifyAndConnect(tagProb: TagProb, row: Int, column: Int, tail: ExtractedEntry): ExtractedEntry? {
   508→        val newEntry = ExtractedEntry(row, column, tagProb, offset)
   509→        return newEntry.next(tail)
   510→    }
