   512→    private fun finalCheck(headEntry: ExtractedEntry): ExtractedEntry? {
   513→        if (headEntry.posTag() == PosTag.J) {
   514→            return null
   515→        }
   516→
   517→        var count = 0
   518→        if (headEntry.entryCount() >= 2) {
   519→            var current: ExtractedEntry? = headEntry
   520→            while (current != null) {
   521→                if (current.column() > 1) {
   522→                    break
   523→                } else {
   524→                    count++
   525→                }
   526→                current = current.next()
   527→            }
   528→        }
   529→
   530→        if (count == headEntry.entryCount()) {
   531→            if (headEntry.last().posTag() == PosTag.J) {
   532→                return headEntry
   533→            }
   534→            return null
   535→        }
   536→        return headEntry
   537→    }
