   554→
   555→        constructor(row: Int, column: Int, tagProb: TagProb) : this(row, column, tagProb, 0.0)
   556→
   557→        constructor(row: Int, column: Int, tagProb: TagProb, scoreAdd: Double) {
   558→            this.row = row
