   574→        fun posTag(): PosTag = tagProb.posTag()
   575→
   576→        fun tagProb(tagProb: TagProb) {
   577→            this.score -= this.tagProb.prob()
   578→            this.tagProb = tagProb
   579→            this.score += tagProb.prob()
